#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void setup() {
  // Инициализация USB и клавиатуры
  USB.begin();
  Keyboard.begin();

  // Даем компьютеру время (3 секунды), чтобы распознать плату как клавиатуру
  delay(3000);

  // 1. Открываем окно "Выполнить" (Win + R)
  Keyboard.press(KEY_LEFT_GUI); // Клавиша Windows
  Keyboard.press('r');           // Клавиша R
  delay(100);                    // Небольшая пауза
  Keyboard.releaseAll();         // Отпускаем обе клавиши
  delay(1000);                   // Ждем, пока откроется окно

  // 2. Вводим "cmd" и нажимаем Enter
  Keyboard.print("cmd");
  delay(100);
  Keyboard.write(KEY_RETURN); // Нажимаем Enter
  delay(1500);                // Ждем открытия командной строки

  // 3. Вводим первую команду "color 2"
  Keyboard.print("color 2");
  delay(100);
  Keyboard.write(KEY_RETURN);
  delay(500); // Ждем выполнения

  // 4. Вводим вторую команду "dir/s" и нажимаем Enter
  Keyboard.print("dir/s");
  delay(100);
  Keyboard.write(KEY_RETURN);

  // Опционально: можно отключить HID, чтобы плата не "мешала" после выполнения
  // Keyboard.end(); 
}

void loop() {
  // В этом скетче ничего не повторяется
}
